(() => {
  "use strict";
  const practiceData = {
    filters: [
      { key: "section", label: "Section", options: ["Introduction", "Direct Revenue and Cost Models", "One-Component Models", "Two-Component Models", "Three-Component Models", "Complete Four-Component Models"] },
      { key: "layer1", label: "Layer 1: Number of components", options: ["Direct", "1 component", "2 components", "3 components", "4 components"] },
      { key: "layer2", label: "Layer 2: Component structure", options: ["AV", "SV", "AF", "SF"], descriptions: { AV: "Alternative-based Variable", SV: "State-based Variable", AF: "Alternative-based Fixed", SF: "State-based Fixed" } }
    ],
    problems: [{"id": "problem-1", "name": "Introductory General Problem (C1--C3)", "section": "Introduction", "layer1": "Direct", "layer2": [], "descriptionHtml": "<p>A school enterprise chooses $A_1$ or $A_2$ before demand is $S_1$ or $S_2$. The consequence is profit in thousand USD. Total revenues are $$\\begin{aligned}\n\tR(A_1,S_1)&=20,\n\t&\n\tR(A_1,S_2)&=13,\n\t\\\\\n\tR(A_2,S_1)&=18,\n\t&\n\tR(A_2,S_2)&=15.\n\\end{aligned}$$ The directly supplied total costs are $$\\begin{aligned}\n\tC(A_1,S_1)&=9,\n\t&\n\tC(A_1,S_2)&=8,\n\t\\\\\n\tC(A_2,S_1)&=10,\n\t&\n\tC(A_2,S_2)&=9.\n\\end{aligned}$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpret the decision elements.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Build the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting the decision.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td>$A_1$; $A_2$<\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td>$S_1$; $S_2$<\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Demand revealed after the enterprise choice<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each alternative&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}, {"title": "C3: Calculating revenue, cost, and payoff.", "contentHtml": "\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td><p>20<\/p><\/td><td><p>9<\/p><\/td><td>$20-9=11$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td><p>13<\/p><\/td><td><p>8<\/p><\/td><td>$13-8=5$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td><p>18<\/p><\/td><td><p>10<\/p><\/td><td>$18-10=8$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td><p>15<\/p><\/td><td><p>9<\/p><\/td><td>$15-9=6$<\/td><\/tr><\/tbody><\/table><\/div>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\">$S_1$<\/th><th scope=\"col\">$S_2$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$A_1$<\/th><td><p>11<\/p><\/td><td><p>5<\/p><\/td><\/tr><tr><th scope=\"row\">$A_2$<\/th><td><p>8<\/p><\/td><td><p>6<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-2", "name": "Advanced General Problem (C1--C3)", "section": "Introduction", "layer1": "4 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A community business chooses $A_1$ or $A_2$ before demand is $S_1$ or $S_2$. The quantities are $$\\begin{aligned}\n\tq(A_1,S_1)&=2,\n\t&\n\tq(A_1,S_2)&=1,\n\t\\\\\n\tq(A_2,S_1)&=3,\n\t&\n\tq(A_2,S_2)&=2.\n\\end{aligned}$$<\/p>\n<p>In thousand USD, the alternative-based revenue rates are $$r^A(A_1)=10,\n\\qquad\nr^A(A_2)=11,$$ and the state-based revenue rates are $$r^S(S_1)=5,\n\\qquad\nr^S(S_2)=3.$$ The alternative-based fixed revenues are $$F^{R,A}(A_1)=7,\n\\qquad\nF^{R,A}(A_2)=9,$$ and the state-based fixed revenues are $$F^{R,S}(S_1)=6,\n\\qquad\nF^{R,S}(S_2)=7.$$<\/p>\n<p>The alternative-based cost rates are $$c^A(A_1)=3,\n\\qquad\nc^A(A_2)=4,$$ and the state-based cost rates are $$c^S(S_1)=1,\n\\qquad\nc^S(S_2)=2.$$ The alternative-based fixed costs are $$F^{C,A}(A_1)=8,\n\\qquad\nF^{C,A}(A_2)=10,$$ and the state-based fixed costs are $$F^{C,S}(S_1)=5,\n\\qquad\nF^{C,S}(S_2)=3.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpret the decision elements.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Build the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting the decision.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td>$A_1$; $A_2$<\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td>$S_1$; $S_2$<\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Demand revealed after the business choice<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD from the complete revenue and cost models<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>For every alternative&ndash;state pair, revenue and cost are calculated independently: $$\\begin{aligned}\n\tR(A_i,S_j)\n\t={}&\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t={}&\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t={}&\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating revenue, cost, and payoff.", "contentHtml": "\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$2(10+5)+7+6=43$<\/td><td>$2(3+1)+8+5=21$<\/td><td>$43-21=22$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$1(10+3)+7+7=27$<\/td><td>$1(3+2)+8+3=16$<\/td><td>$27-16=11$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$3(11+5)+9+6=63$<\/td><td>$3(4+1)+10+5=30$<\/td><td>$63-30=33$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$2(11+3)+9+7=44$<\/td><td>$2(4+2)+10+3=25$<\/td><td>$44-25=19$<\/td><\/tr><\/tbody><\/table><\/div>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\">$S_1$<\/th><th scope=\"col\">$S_2$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$A_1$<\/th><td><p>22<\/p><\/td><td><p>11<\/p><\/td><\/tr><tr><th scope=\"row\">$A_2$<\/th><td><p>33<\/p><\/td><td><p>19<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-3", "name": "Local Café Investment (C1--C3)", "section": "Direct Revenue and Cost Models", "layer1": "Direct", "layer2": [], "descriptionHtml": "<p>A small café is deciding whether to launch a new line of artisan desserts. The transaction is daily café sales, where revenue is earned from sales and costs include the resources required to operate each menu option. The owner must choose between:<\/p>\n\t<ol>\n\t\t<li>$A_1$: <strong>Launch the dessert line<\/strong>\n\t\t<li>$A_2$: <strong>Keep the current menu<\/strong>\n\t<\/ol>\n<p>The possible states of nature are: <ol> <li>$S_1$: High traffic <li>$S_2$: Low traffic <\/ol><\/p>\n<p>The directly estimated revenues and costs, in thousand USD, are: <ol> <li>Launch dessert line: <ol> <li>High traffic: $R(A_1,S_1)=58$, $C(A_1,S_1)=16$<\/p>\n\t\t\t<li>Low traffic:\n\t\t\t$R(A_1,S_2)=27$, $C(A_1,S_2)=19$\n\t\t<\/ol>\n\t\t<li>Keep current menu:\n\t\t<ol>\n\t\t\t<li>High traffic:\n\t\t\t$R(A_2,S_1)=49$, $C(A_2,S_1)=21$\n\t\t\t<li>Low traffic:\n\t\t\t$R(A_2,S_2)=41$, $C(A_2,S_2)=21$\n\t\t<\/ol>\n\t<\/ol>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Launch dessert line; Keep current menu<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High traffic; Low traffic<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Actual foot traffic after the decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each alternative&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j).$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td><p>58<\/p><\/td><td><p>16<\/p><\/td><td>$58-16=42$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td><p>27<\/p><\/td><td><p>19<\/p><\/td><td>$27-19=8$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td><p>49<\/p><\/td><td><p>21<\/p><\/td><td>$49-21=28$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td><p>41<\/p><\/td><td><p>21<\/p><\/td><td>$41-21=20$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High traffic<\/p><\/th><th scope=\"col\"><p>Low traffic<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Launch dessert line<\/p><\/th><td><p>42<\/p><\/td><td><p>8<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Keep current menu<\/p><\/th><td><p>28<\/p><\/td><td><p>20<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-4", "name": "Green Energy Production Mix (C1--C3)", "section": "Direct Revenue and Cost Models", "layer1": "Direct", "layer2": [], "descriptionHtml": "<p>A renewable-energy company must select an electricity-generation mix. The transaction is annual electricity sales, where revenue is earned from electricity generated and sold, while costs arise from operating the selected generation system.<\/p>\n<p>The company is comparing three alternatives: <ol> <li>$A_1$: Build wind turbines <li>$A_2$: Build solar farms <li>$A_3$: Build a balanced hybrid system <\/ol><\/p>\n<p>Three weather states are possible: <ol> <li>$S_1$: Windy <li>$S_2$: Sunny <li>$S_3$: Cloudy <\/ol><\/p>\n<p>The directly estimated revenues and costs, in thousand USD, are: <ol> <li>Wind turbines: <ol> <li>Windy: $R(A_1,S_1)=132$, $C(A_1,S_1)=42$<\/p>\n\t\t\t<li>Sunny:\n\t\t\t$R(A_1,S_2)=78$, $C(A_1,S_2)=33$\n\t\t\t<li>Cloudy:\n\t\t\t$R(A_1,S_3)=62$, $C(A_1,S_3)=32$\n\t\t<\/ol>\n\t\t<li>Solar farms:\n\t\t<ol>\n\t\t\t<li>Windy:\n\t\t\t$R(A_2,S_1)=77$, $C(A_2,S_1)=42$\n\t\t\t<li>Sunny:\n\t\t\t$R(A_2,S_2)=143$, $C(A_2,S_2)=48$\n\t\t\t<li>Cloudy:\n\t\t\t$R(A_2,S_3)=63$, $C(A_2,S_3)=38$\n\t\t<\/ol>\n\t\t<li>Hybrid system:\n\t\t<ol>\n\t\t\t<li>Windy:\n\t\t\t$R(A_3,S_1)=112$, $C(A_3,S_1)=42$\n\t\t\t<li>Sunny:\n\t\t\t$R(A_3,S_2)=107$, $C(A_3,S_2)=42$\n\t\t\t<li>Cloudy:\n\t\t\t$R(A_3,S_3)=96$, $C(A_3,S_3)=36$\n\t\t<\/ol>\n\t<\/ol>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Wind turbines; Solar farms; Hybrid system<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Windy; Sunny; Cloudy<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Weather outcome affecting electricity generation<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each strategy&ndash;weather combination<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j).$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td><p>132<\/p><\/td><td><p>42<\/p><\/td><td>$132-42=90$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td><p>78<\/p><\/td><td><p>33<\/p><\/td><td>$78-33=45$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_3)$<\/th><td><p>62<\/p><\/td><td><p>32<\/p><\/td><td>$62-32=30$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td><p>77<\/p><\/td><td><p>42<\/p><\/td><td>$77-42=35$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td><p>143<\/p><\/td><td><p>48<\/p><\/td><td>$143-48=95$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_3)$<\/th><td><p>63<\/p><\/td><td><p>38<\/p><\/td><td>$63-38=25$<\/td><\/tr><tr><th scope=\"row\">$(A_3,S_1)$<\/th><td><p>112<\/p><\/td><td><p>42<\/p><\/td><td>$112-42=70$<\/td><\/tr><tr><th scope=\"row\">$(A_3,S_2)$<\/th><td><p>107<\/p><\/td><td><p>42<\/p><\/td><td>$107-42=65$<\/td><\/tr><tr><th scope=\"row\">$(A_3,S_3)$<\/th><td><p>96<\/p><\/td><td><p>36<\/p><\/td><td>$96-36=60$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Strategy<\/p><\/th><th scope=\"col\"><p>Windy<\/p><\/th><th scope=\"col\"><p>Sunny<\/p><\/th><th scope=\"col\"><p>Cloudy<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Wind turbines<\/p><\/th><td><p>90<\/p><\/td><td><p>45<\/p><\/td><td><p>30<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Solar farms<\/p><\/th><td><p>35<\/p><\/td><td><p>95<\/p><\/td><td><p>25<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Hybrid system<\/p><\/th><td><p>70<\/p><\/td><td><p>65<\/p><\/td><td><p>60<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-5", "name": "Custom Printing Product Line (C1--C3)", "section": "One-Component Models", "layer1": "1 component", "layer2": ["AV", "SV"], "descriptionHtml": "<p>A custom-printing cooperative must select the product line that it will produce before market conditions are known. The transaction is the sale of production lots. Revenue per lot depends on the selected product, while cost per lot depends on the market state.<\/p>\n<p>The cooperative is comparing two alternatives: <ol> <li>$A_1$: Produce premium notebooks <li>$A_2$: Produce canvas bags <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong demand and stable material prices <li>$S_2$: Weak demand and higher material prices <\/ol><\/p>\n<p>The quantities, measured in production lots, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=6,\n\t\t&\n\t\tq(A_1,S_2)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=5,\n\t\t&\n\t\tq(A_2,S_2)&=3.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per lot, are $$r^A(A_1)=12,\n\t\\qquad\n\tr^A(A_2)=15.$$<\/p>\n<p>The state-based cost rates, in thousand USD per lot, are $$c^S(S_1)=5,\n\t\\qquad\n\tc^S(S_2)=8.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Produce premium notebooks; Produce canvas bags<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong demand and stable material prices; Weak demand and higher material prices<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Market conditions revealed after the product-line decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each product-line&ndash;market-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>The only revenue component is an alternative-based variable component: $$R(A_i,S_j)=q(A_i,S_j)r^A(A_i).$$ The only cost component is a state-based variable component: $$C(A_i,S_j)=q(A_i,S_j)c^S(S_j).$$ Therefore, $$P(A_i,S_j)\n=\nq(A_i,S_j)r^A(A_i)\n-\nq(A_i,S_j)c^S(S_j).$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate revenue and cost independently: $$\\begin{aligned}\n\tR(A_i,S_j)&=q(A_i,S_j)r^A(A_i),\n\t\\\\\n\tC(A_i,S_j)&=q(A_i,S_j)c^S(S_j),\n\t\\\\\n\tP(A_i,S_j)&=R(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$6(12)=72$<\/td><td>$6(5)=30$<\/td><td>$72-30=42$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$4(12)=48$<\/td><td>$4(8)=32$<\/td><td>$48-32=16$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$5(15)=75$<\/td><td>$5(5)=25$<\/td><td>$75-25=50$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$3(15)=45$<\/td><td>$3(8)=24$<\/td><td>$45-24=21$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong demand and stable prices<\/p><\/th><th scope=\"col\"><p>Weak demand and higher prices<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Premium notebooks<\/p><\/th><td><p>42<\/p><\/td><td><p>16<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Canvas bags<\/p><\/th><td><p>50<\/p><\/td><td><p>21<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-6", "name": "Event Equipment Fleet (C1--C3)", "section": "One-Component Models", "layer1": "1 component", "layer2": ["SV", "AF"], "descriptionHtml": "<p>An event-equipment provider must choose the size of the fleet that it will prepare before rental demand is known. Revenue per rental contract depends on the demand state, while the preparation cost is a fixed amount determined by the selected fleet.<\/p>\n<p>The provider is comparing two alternatives: <ol> <li>$A_1$: Prepare a compact fleet <li>$A_2$: Prepare an expanded fleet <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High rental demand <li>$S_2$: Low rental demand <\/ol><\/p>\n<p>The numbers of rental contracts are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=6,\n\t\t&\n\t\tq(A_1,S_2)&=3,\n\t\t\\\\\n\t\tq(A_2,S_1)&=8,\n\t\t&\n\t\tq(A_2,S_2)&=4.\n\t\\end{aligned}$$<\/p>\n<p>The state-based revenue rates, in thousand USD per contract, are $$r^S(S_1)=9,\n\t\\qquad\n\tr^S(S_2)=6.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=22,\n\t\\qquad\n\tF^{C,A}(A_2)=34.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Prepare a compact fleet; Prepare an expanded fleet<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High rental demand; Low rental demand<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Rental demand revealed after the fleet-size decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each fleet&ndash;demand pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>The only revenue component is a state-based variable component: $$R(A_i,S_j)=q(A_i,S_j)r^S(S_j).$$ The only cost component is an alternative-based fixed component: $$C(A_i,S_j)=F^{C,A}(A_i).$$ Therefore, $$P(A_i,S_j)\n=\nq(A_i,S_j)r^S(S_j)\n-\nF^{C,A}(A_i).$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)&=q(A_i,S_j)r^S(S_j),\n\t\\\\\n\tC(A_i,S_j)&=F^{C,A}(A_i),\n\t\\\\\n\tP(A_i,S_j)&=R(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$6(9)=54$<\/td><td>$22$<\/td><td>$54-22=32$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$3(6)=18$<\/td><td>$22$<\/td><td>$18-22=-4$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$8(9)=72$<\/td><td>$34$<\/td><td>$72-34=38$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$4(6)=24$<\/td><td>$34$<\/td><td>$24-34=-10$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High rental demand<\/p><\/th><th scope=\"col\"><p>Low rental demand<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Compact fleet<\/p><\/th><td><p>32<\/p><\/td><td>$-4$<\/td><\/tr><tr><th scope=\"row\"><p>Expanded fleet<\/p><\/th><td><p>38<\/p><\/td><td>$-10$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The negative payoffs in the low-demand state represent losses because the fixed preparation cost is greater than the revenue earned.<\/p>"}]}, {"id": "problem-7", "name": "Community Arts Sponsorship (C1--C3)", "section": "One-Component Models", "layer1": "1 component", "layer2": ["AF", "SF"], "descriptionHtml": "<p>A community arts organisation must select a sponsorship agreement before the event requirements are confirmed. Each agreement provides a fixed sponsorship payment, while the event incurs a fixed regulatory and safety cost determined by the state of nature.<\/p>\n<p>The organisation is comparing two alternatives: <ol> <li>$A_1$: Accept the standard sponsorship agreement <li>$A_2$: Accept the premium sponsorship agreement <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Routine permit requirements <li>$S_2$: Enhanced safety requirements <\/ol><\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=52,\n\t\\qquad\n\tF^{R,A}(A_2)=68.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=18,\n\t\\qquad\n\tF^{C,S}(S_2)=31.$$<\/p>\n<p>Neither model contains a variable component, so quantity is not required.<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Accept the standard sponsorship agreement; Accept the premium sponsorship agreement<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Routine permit requirements; Enhanced safety requirements<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Event requirements confirmed after the sponsorship decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each sponsorship&ndash;requirement pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>The only revenue component is an alternative-based fixed component: $$R(A_i,S_j)=F^{R,A}(A_i).$$ The only cost component is a state-based fixed component: $$C(A_i,S_j)=F^{C,S}(S_j).$$ Therefore, $$P(A_i,S_j)\n=\nF^{R,A}(A_i)\n-\nF^{C,S}(S_j).$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)&=F^{R,A}(A_i),\n\t\\\\\n\tC(A_i,S_j)&=F^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)&=R(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td><p>52<\/p><\/td><td><p>18<\/p><\/td><td>$52-18=34$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td><p>52<\/p><\/td><td><p>31<\/p><\/td><td>$52-31=21$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td><p>68<\/p><\/td><td><p>18<\/p><\/td><td>$68-18=50$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td><p>68<\/p><\/td><td><p>31<\/p><\/td><td>$68-31=37$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Routine requirements<\/p><\/th><th scope=\"col\"><p>Enhanced requirements<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard sponsorship<\/p><\/th><td><p>34<\/p><\/td><td><p>21<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Premium sponsorship<\/p><\/th><td><p>50<\/p><\/td><td><p>37<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-8", "name": "Distribution Contract Fulfilment (C1--C3)", "section": "One-Component Models", "layer1": "1 component", "layer2": ["SF", "AV"], "descriptionHtml": "<p>A distribution company must choose a fulfilment method before the volume of a new contract is known. The contract provides a fixed payment determined by the realised volume state, while the processing cost per unit depends on the selected fulfilment method.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use manual packing <li>$A_2$: Use automated packing <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Standard-volume contract <li>$S_2$: High-volume contract <\/ol><\/p>\n<p>The quantities, measured in hundreds of processed orders, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=4,\n\t\t&\n\t\tq(A_1,S_2)&=7,\n\t\t\\\\\n\t\tq(A_2,S_1)&=5,\n\t\t&\n\t\tq(A_2,S_2)&=8.\n\t\\end{aligned}$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=70,\n\t\\qquad\n\tF^{R,S}(S_2)=104.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per hundred orders, are $$c^A(A_1)=7,\n\t\\qquad\n\tc^A(A_2)=5.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use manual packing; Use automated packing<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Standard-volume contract; High-volume contract<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Contract volume revealed after the fulfilment-method decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each fulfilment-method&ndash;volume pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>The only revenue component is a state-based fixed component: $$R(A_i,S_j)=F^{R,S}(S_j).$$ The only cost component is an alternative-based variable component: $$C(A_i,S_j)=q(A_i,S_j)c^A(A_i).$$ Therefore, $$P(A_i,S_j)\n=\nF^{R,S}(S_j)\n-\nq(A_i,S_j)c^A(A_i).$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)&=F^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)&=q(A_i,S_j)c^A(A_i),\n\t\\\\\n\tP(A_i,S_j)&=R(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$70$<\/td><td>$4(7)=28$<\/td><td>$70-28=42$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$104$<\/td><td>$7(7)=49$<\/td><td>$104-49=55$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$70$<\/td><td>$5(5)=25$<\/td><td>$70-25=45$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$104$<\/td><td>$8(5)=40$<\/td><td>$104-40=64$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Standard-volume contract<\/p><\/th><th scope=\"col\"><p>High-volume contract<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Manual packing<\/p><\/th><td><p>42<\/p><\/td><td><p>55<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Automated packing<\/p><\/th><td><p>45<\/p><\/td><td><p>64<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-9", "name": "Farm Produce Subscription Plans (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["AV", "SV", "SF"], "descriptionHtml": "<p>A farm cooperative must choose a produce-subscription plan before seasonal market conditions are known. Revenue per subscription consists of a rate determined by the selected plan and an additional rate determined by the market state. Costs consist of a plan-based variable cost and a fixed distribution cost determined by the state.<\/p>\n<p>The cooperative is comparing two alternatives: <ol> <li>$A_1$: Offer a standard produce box <li>$A_2$: Offer a premium produce box <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong seasonal demand <li>$S_2$: Weak seasonal demand <\/ol><\/p>\n<p>The quantities, measured in hundreds of subscriptions, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=7,\n\t\t&\n\t\tq(A_1,S_2)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=6,\n\t\t&\n\t\tq(A_2,S_2)&=3.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per hundred subscriptions, are $$r^A(A_1)=8,\n\t\\qquad\n\tr^A(A_2)=11.$$<\/p>\n<p>The state-based revenue rates are $$r^S(S_1)=3,\n\t\\qquad\n\tr^S(S_2)=1.$$<\/p>\n<p>The alternative-based cost rates are $$c^A(A_1)=4,\n\t\\qquad\n\tc^A(A_2)=6.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=9,\n\t\\qquad\n\tF^{C,S}(S_2)=13.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Offer a standard produce box; Offer a premium produce box<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong seasonal demand; Weak seasonal demand<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Seasonal market conditions revealed after the subscription-plan decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each plan&ndash;market-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right].$$<\/p>\n<p>Cost contains an alternative-based variable component and a state-based fixed component: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^A(A_i)+F^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n-\n\\left[\nq(A_i,S_j)c^A(A_i)+F^{C,S}(S_j)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right],\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^A(A_i)+F^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$7(8+3)=77$<\/td><td>$7(4)+9=37$<\/td><td>$77-37=40$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$4(8+1)=36$<\/td><td>$4(4)+13=29$<\/td><td>$36-29=7$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$6(11+3)=84$<\/td><td>$6(6)+9=45$<\/td><td>$84-45=39$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$3(11+1)=36$<\/td><td>$3(6)+13=31$<\/td><td>$36-31=5$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong seasonal demand<\/p><\/th><th scope=\"col\"><p>Weak seasonal demand<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard produce box<\/p><\/th><td><p>40<\/p><\/td><td><p>7<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Premium produce box<\/p><\/th><td><p>39<\/p><\/td><td><p>5<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-10", "name": "Mobile Catering Configuration (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["AV", "AF", "SV"], "descriptionHtml": "<p>A mobile-catering company must choose a service configuration before event demand and ingredient-market conditions are known. Revenue consists of a configuration-based rate per service order and a fixed booking payment determined by the selected configuration. Cost consists of a state-based rate per order and a fixed setup cost determined by the configuration.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Prepare a compact catering station <li>$A_2$: Prepare a full mobile kitchen <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Busy event with stable ingredient prices <li>$S_2$: Quiet event with higher ingredient prices <\/ol><\/p>\n<p>The quantities, measured in hundreds of service orders, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=8,\n\t\t&\n\t\tq(A_1,S_2)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=10,\n\t\t&\n\t\tq(A_2,S_2)&=5.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per hundred orders, are $$r^A(A_1)=7,\n\t\\qquad\n\tr^A(A_2)=9.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=18,\n\t\\qquad\n\tF^{R,A}(A_2)=25.$$<\/p>\n<p>The state-based cost rates, in thousand USD per hundred orders, are $$c^S(S_1)=3,\n\t\\qquad\n\tc^S(S_2)=5.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=20,\n\t\\qquad\n\tF^{C,A}(A_2)=32.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Prepare a compact catering station; Prepare a full mobile kitchen<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Busy event with stable ingredient prices; Quiet event with higher ingredient prices<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Event demand and ingredient-market conditions revealed after the configuration decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each configuration&ndash;market-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based variable and fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^A(A_i)+F^{R,A}(A_i).$$<\/p>\n<p>Cost contains a state-based variable component and an alternative-based fixed component: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^S(S_j)+F^{C,A}(A_i).$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\n\\left[\nq(A_i,S_j)r^A(A_i)+F^{R,A}(A_i)\n\\right]\n-\n\\left[\nq(A_i,S_j)c^S(S_j)+F^{C,A}(A_i)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^A(A_i)+F^{R,A}(A_i),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^S(S_j)+F^{C,A}(A_i),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$8(7)+18=74$<\/td><td>$8(3)+20=44$<\/td><td>$74-44=30$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$4(7)+18=46$<\/td><td>$4(5)+20=40$<\/td><td>$46-40=6$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$10(9)+25=115$<\/td><td>$10(3)+32=62$<\/td><td>$115-62=53$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$5(9)+25=70$<\/td><td>$5(5)+32=57$<\/td><td>$70-57=13$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Busy event<\/p><\/th><th scope=\"col\"><p>Quiet event<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Compact catering station<\/p><\/th><td><p>30<\/p><\/td><td><p>6<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Full mobile kitchen<\/p><\/th><td><p>53<\/p><\/td><td><p>13<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-11", "name": "Online Training Programme (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["AV", "SV", "SF"], "descriptionHtml": "<p>An online-training provider must select a programme before enrolment conditions are known. Revenue consists of a programme-based rate per enrolment group and a fixed payment determined by the enrolment state. Cost consists of a state-based delivery rate and a fixed platform cost determined by the state.<\/p>\n<p>The provider is comparing two alternatives: <ol> <li>$A_1$: Offer the foundation programme <li>$A_2$: Offer the advanced programme <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Corporate enrolment <li>$S_2$: Individual enrolment <\/ol><\/p>\n<p>The quantities, measured in enrolment groups, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=5,\n\t\t&\n\t\tq(A_1,S_2)&=3,\n\t\t\\\\\n\t\tq(A_2,S_1)&=4,\n\t\t&\n\t\tq(A_2,S_2)&=2.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per group, are $$r^A(A_1)=14,\n\t\\qquad\n\tr^A(A_2)=20.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=12,\n\t\\qquad\n\tF^{R,S}(S_2)=7.$$<\/p>\n<p>The state-based cost rates, in thousand USD per group, are $$c^S(S_1)=6,\n\t\\qquad\n\tc^S(S_2)=8.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=10,\n\t\\qquad\n\tF^{C,S}(S_2)=14.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Offer the foundation programme; Offer the advanced programme<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Corporate enrolment; Individual enrolment<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Enrolment type revealed after the programme decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each programme&ndash;enrolment pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains an alternative-based variable component and a state-based fixed component: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^A(A_i)+F^{R,S}(S_j).$$<\/p>\n<p>Cost contains state-based variable and fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^S(S_j)+F^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\n\\left[\nq(A_i,S_j)r^A(A_i)+F^{R,S}(S_j)\n\\right]\n-\n\\left[\nq(A_i,S_j)c^S(S_j)+F^{C,S}(S_j)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^A(A_i)+F^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^S(S_j)+F^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$5(14)+12=82$<\/td><td>$5(6)+10=40$<\/td><td>$82-40=42$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$3(14)+7=49$<\/td><td>$3(8)+14=38$<\/td><td>$49-38=11$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$4(20)+12=92$<\/td><td>$4(6)+10=34$<\/td><td>$92-34=58$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$2(20)+7=47$<\/td><td>$2(8)+14=30$<\/td><td>$47-30=17$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Corporate enrolment<\/p><\/th><th scope=\"col\"><p>Individual enrolment<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Foundation programme<\/p><\/th><td><p>42<\/p><\/td><td><p>11<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Advanced programme<\/p><\/th><td><p>58<\/p><\/td><td><p>17<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-12", "name": "Community Venue Membership (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["SV", "AF", "SF"], "descriptionHtml": "<p>A community organisation must select a venue-membership plan before booking conditions and permit requirements are known. Revenue consists of a state-based rate per booking and a fixed sponsorship payment determined by the selected membership plan. Costs consist of two fixed components: one determined by the plan and one determined by the state.<\/p>\n<p>The organisation is comparing two alternatives: <ol> <li>$A_1$: Select the standard venue membership <li>$A_2$: Select the expanded venue membership <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High booking demand <li>$S_2$: Low booking demand <\/ol><\/p>\n<p>The numbers of bookings are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=6,\n\t\t&\n\t\tq(A_1,S_2)&=3,\n\t\t\\\\\n\t\tq(A_2,S_1)&=8,\n\t\t&\n\t\tq(A_2,S_2)&=4.\n\t\\end{aligned}$$<\/p>\n<p>The state-based revenue rates, in thousand USD per booking, are $$r^S(S_1)=10,\n\t\\qquad\n\tr^S(S_2)=7.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=15,\n\t\\qquad\n\tF^{R,A}(A_2)=22.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=28,\n\t\\qquad\n\tF^{C,A}(A_2)=40.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=8,\n\t\\qquad\n\tF^{C,S}(S_2)=13.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Select the standard venue membership; Select the expanded venue membership<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High booking demand; Low booking demand<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Booking demand revealed after the membership-plan decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each membership&ndash;demand pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains a state-based variable component and an alternative-based fixed component: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^S(S_j)+F^{R,A}(A_i).$$<\/p>\n<p>Cost contains alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nF^{C,A}(A_i)+F^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\n\\left[\nq(A_i,S_j)r^S(S_j)+F^{R,A}(A_i)\n\\right]\n-\n\\left[\nF^{C,A}(A_i)+F^{C,S}(S_j)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^S(S_j)+F^{R,A}(A_i),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tF^{C,A}(A_i)+F^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$6(10)+15=75$<\/td><td>$28+8=36$<\/td><td>$75-36=39$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$3(7)+15=36$<\/td><td>$28+13=41$<\/td><td>$36-41=-5$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$8(10)+22=102$<\/td><td>$40+8=48$<\/td><td>$102-48=54$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$4(7)+22=50$<\/td><td>$40+13=53$<\/td><td>$50-53=-3$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High booking demand<\/p><\/th><th scope=\"col\"><p>Low booking demand<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard venue membership<\/p><\/th><td><p>39<\/p><\/td><td>$-5$<\/td><\/tr><tr><th scope=\"row\"><p>Expanded venue membership<\/p><\/th><td><p>54<\/p><\/td><td>$-3$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The negative payoffs under low booking demand represent losses because the combined fixed costs exceed the revenue earned.<\/p>"}]}, {"id": "problem-13", "name": "Urban Delivery Fleet (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["AV", "SV", "SF"], "descriptionHtml": "<p>An urban-delivery company must choose a fleet configuration before delivery demand and traffic conditions are known. Revenue consists of a state-based rate per delivery batch and a fixed performance payment determined by the state. Variable cost per batch combines a fleet-based operating rate and a state-based traffic surcharge.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use a conventional van fleet <li>$A_2$: Use an electric cargo-bike fleet <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High demand with light traffic <li>$S_2$: Low demand with heavy traffic <\/ol><\/p>\n<p>The quantities, measured in delivery batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=9,\n\t\t&\n\t\tq(A_1,S_2)&=5,\n\t\t\\\\\n\t\tq(A_2,S_1)&=12,\n\t\t&\n\t\tq(A_2,S_2)&=6.\n\t\\end{aligned}$$<\/p>\n<p>The state-based revenue rates, in thousand USD per batch, are $$r^S(S_1)=8,\n\t\\qquad\n\tr^S(S_2)=6.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=14,\n\t\\qquad\n\tF^{R,S}(S_2)=8.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per batch, are $$c^A(A_1)=3,\n\t\\qquad\n\tc^A(A_2)=2.$$<\/p>\n<p>The state-based cost rates, in thousand USD per batch, are $$c^S(S_1)=1,\n\t\\qquad\n\tc^S(S_2)=3.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use a conventional van fleet; Use an electric cargo-bike fleet<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High demand with light traffic; Low demand with heavy traffic<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Delivery demand and traffic conditions revealed after the fleet decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each fleet&ndash;market-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains state-based variable and fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^S(S_j)+F^{R,S}(S_j).$$<\/p>\n<p>Cost contains alternative-based and state-based variable components: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right].$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\n\\left[\nq(A_i,S_j)r^S(S_j)+F^{R,S}(S_j)\n\\right]\n-\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^S(S_j)+F^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right],\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$9(8)+14=86$<\/td><td>$9(3+1)=36$<\/td><td>$86-36=50$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$5(6)+8=38$<\/td><td>$5(3+3)=30$<\/td><td>$38-30=8$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$12(8)+14=110$<\/td><td>$12(2+1)=36$<\/td><td>$110-36=74$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$6(6)+8=44$<\/td><td>$6(2+3)=30$<\/td><td>$44-30=14$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High demand, light traffic<\/p><\/th><th scope=\"col\"><p>Low demand, heavy traffic<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Conventional van fleet<\/p><\/th><td><p>50<\/p><\/td><td><p>8<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Electric cargo-bike fleet<\/p><\/th><td><p>74<\/p><\/td><td><p>14<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-14", "name": "Data-Service Contract (C1--C3)", "section": "Two-Component Models", "layer1": "2 components", "layer2": ["AV", "AF", "SF"], "descriptionHtml": "<p>A data-services company must choose a processing method before the requirements of a new contract are confirmed. Revenue consists of a fixed payment determined by the selected method and a fixed service-level payment determined by the contract state. Cost consists of a method-based processing rate and a fixed implementation cost determined by the selected method.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use standard data processing <li>$A_2$: Use automated data processing <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Standard-volume contract <li>$S_2$: High-volume contract <\/ol><\/p>\n<p>The quantities, measured in processing batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=4,\n\t\t&\n\t\tq(A_1,S_2)&=7,\n\t\t\\\\\n\t\tq(A_2,S_1)&=5,\n\t\t&\n\t\tq(A_2,S_2)&=9.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=55,\n\t\\qquad\n\tF^{R,A}(A_2)=72.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=16,\n\t\\qquad\n\tF^{R,S}(S_2)=9.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per batch, are $$c^A(A_1)=6,\n\t\\qquad\n\tc^A(A_2)=4.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=18,\n\t\\qquad\n\tF^{C,A}(A_2)=31.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use standard data processing; Use automated data processing<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Standard-volume contract; High-volume contract<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Contract requirements confirmed after the processing-method decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each processing-method&ndash;contract-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nF^{R,A}(A_i)+F^{R,S}(S_j).$$<\/p>\n<p>Cost contains alternative-based variable and fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^A(A_i)+F^{C,A}(A_i).$$<\/p>\n<p>Therefore, $$P(A_i,S_j)\n=\n\\left[\nF^{R,A}(A_i)+F^{R,S}(S_j)\n\\right]\n-\n\\left[\nq(A_i,S_j)c^A(A_i)+F^{C,A}(A_i)\n\\right].$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tF^{R,A}(A_i)+F^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^A(A_i)+F^{C,A}(A_i),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$55+16=71$<\/td><td>$4(6)+18=42$<\/td><td>$71-42=29$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$55+9=64$<\/td><td>$7(6)+18=60$<\/td><td>$64-60=4$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$72+16=88$<\/td><td>$5(4)+31=51$<\/td><td>$88-51=37$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$72+9=81$<\/td><td>$9(4)+31=67$<\/td><td>$81-67=14$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Standard-volume contract<\/p><\/th><th scope=\"col\"><p>High-volume contract<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard data processing<\/p><\/th><td><p>29<\/p><\/td><td><p>4<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Automated data processing<\/p><\/th><td><p>37<\/p><\/td><td><p>14<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-15", "name": "Regional Parcel Delivery (C1--C3)", "section": "Three-Component Models", "layer1": "3 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A regional logistics company must select a parcel-delivery plan before demand and traffic conditions are known. Revenue per delivery batch combines a rate determined by the selected plan and a rate determined by the state. The selected plan also provides a fixed service payment. Cost per batch combines a plan-based operating rate and a state-based traffic rate, together with a fixed distribution cost determined by the state.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use the standard delivery plan <li>$A_2$: Use the express delivery plan <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High demand with light traffic <li>$S_2$: Moderate demand with heavy traffic <\/ol><\/p>\n<p>The quantities, measured in hundreds of delivery batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=8,\n\t\t&\n\t\tq(A_1,S_2)&=5,\n\t\t\\\\\n\t\tq(A_2,S_1)&=10,\n\t\t&\n\t\tq(A_2,S_2)&=6.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per hundred delivery batches, are $$r^A(A_1)=9,\n\t\\qquad\n\tr^A(A_2)=11.$$<\/p>\n<p>The state-based revenue rates are $$r^S(S_1)=3,\n\t\\qquad\n\tr^S(S_2)=2.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=16,\n\t\\qquad\n\tF^{R,A}(A_2)=24.$$<\/p>\n<p>The alternative-based cost rates are $$c^A(A_1)=4,\n\t\\qquad\n\tc^A(A_2)=5.$$<\/p>\n<p>The state-based cost rates are $$c^S(S_1)=1,\n\t\\qquad\n\tc^S(S_2)=3.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=10,\n\t\\qquad\n\tF^{C,S}(S_2)=15.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use the standard delivery plan; Use the express delivery plan<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High demand with light traffic; Moderate demand with heavy traffic<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Demand and traffic conditions revealed after the delivery-plan decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each delivery-plan&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components and an alternative-based fixed component: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n+\nF^{R,A}(A_i).$$<\/p>\n<p>Cost contains alternative-based and state-based variable components and a state-based fixed component: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right]\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$8(9+3)+16=112$<\/td><td>$8(4+1)+10=50$<\/td><td>$112-50=62$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$5(9+2)+16=71$<\/td><td>$5(4+3)+15=50$<\/td><td>$71-50=21$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$10(11+3)+24=164$<\/td><td>$10(5+1)+10=70$<\/td><td>$164-70=94$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$6(11+2)+24=102$<\/td><td>$6(5+3)+15=63$<\/td><td>$102-63=39$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High demand, light traffic<\/p><\/th><th scope=\"col\"><p>Moderate demand, heavy traffic<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard delivery plan<\/p><\/th><td><p>62<\/p><\/td><td><p>21<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Express delivery plan<\/p><\/th><td><p>94<\/p><\/td><td><p>39<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-16", "name": "Solar Installation Programme (C1--C3)", "section": "Three-Component Models", "layer1": "3 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A renewable-energy company must select a solar installation programme before customer demand and permit conditions are known. Revenue per installation batch combines a programme-based rate and a state-based market rate, together with a fixed incentive determined by the state. Costs consist of a programme-based variable cost, a fixed setup cost determined by the programme, and a fixed permit cost determined by the state.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Offer the standard-panel programme <li>$A_2$: Offer the high-efficiency-panel programme <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong commercial demand <li>$S_2$: Limited residential demand <\/ol><\/p>\n<p>The quantities, measured in installation batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=7,\n\t\t&\n\t\tq(A_1,S_2)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=6,\n\t\t&\n\t\tq(A_2,S_2)&=3.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per installation batch, are $$r^A(A_1)=12,\n\t\\qquad\n\tr^A(A_2)=18.$$<\/p>\n<p>The state-based revenue rates are $$r^S(S_1)=4,\n\t\\qquad\n\tr^S(S_2)=2.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=20,\n\t\\qquad\n\tF^{R,S}(S_2)=11.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per installation batch, are $$c^A(A_1)=6,\n\t\\qquad\n\tc^A(A_2)=8.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=18,\n\t\\qquad\n\tF^{C,A}(A_2)=25.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=9,\n\t\\qquad\n\tF^{C,S}(S_2)=14.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Offer the standard-panel programme; Offer the high-efficiency-panel programme<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong commercial demand; Limited residential demand<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Customer demand and permit conditions revealed after the programme decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each programme&ndash;market-state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components and a state-based fixed component: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost contains an alternative-based variable component and alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^A(A_i)\n+\nF^{C,A}(A_i)\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)c^A(A_i)\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^A(A_i)\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$7(12+4)+20=132$<\/td><td>$7(6)+18+9=69$<\/td><td>$132-69=63$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$4(12+2)+11=67$<\/td><td>$4(6)+18+14=56$<\/td><td>$67-56=11$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$6(18+4)+20=152$<\/td><td>$6(8)+25+9=82$<\/td><td>$152-82=70$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$3(18+2)+11=71$<\/td><td>$3(8)+25+14=63$<\/td><td>$71-63=8$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong commercial demand<\/p><\/th><th scope=\"col\"><p>Limited residential demand<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard-panel programme<\/p><\/th><td><p>63<\/p><\/td><td><p>11<\/p><\/td><\/tr><tr><th scope=\"row\"><p>High-efficiency-panel programme<\/p><\/th><td><p>70<\/p><\/td><td><p>8<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-17", "name": "Hybrid Conference Production (C1--C3)", "section": "Three-Component Models", "layer1": "3 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>An events company must choose a hybrid-conference production package before attendance and sponsorship conditions are known. Revenue consists of a package-based rate per event segment, a fixed booking payment determined by the selected package, and a fixed sponsorship payment determined by the state. Costs consist of a state-based delivery rate, a fixed setup cost determined by the package, and a fixed licensing cost determined by the state.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use the standard hybrid package <li>$A_2$: Use the immersive hybrid package <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong attendance and sponsorship <li>$S_2$: Limited attendance and sponsorship <\/ol><\/p>\n<p>The quantities, measured in event segments, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=6,\n\t\t&\n\t\tq(A_1,S_2)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=8,\n\t\t&\n\t\tq(A_2,S_2)&=5.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per event segment, are $$r^A(A_1)=13,\n\t\\qquad\n\tr^A(A_2)=16.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=14,\n\t\\qquad\n\tF^{R,A}(A_2)=22.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=18,\n\t\\qquad\n\tF^{R,S}(S_2)=9.$$<\/p>\n<p>The state-based cost rates, in thousand USD per event segment, are $$c^S(S_1)=5,\n\t\\qquad\n\tc^S(S_2)=7.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=24,\n\t\\qquad\n\tF^{C,A}(A_2)=37.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=8,\n\t\\qquad\n\tF^{C,S}(S_2)=13.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use the standard hybrid package; Use the immersive hybrid package<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong attendance and sponsorship; Limited attendance and sponsorship<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Attendance and sponsorship conditions revealed after the package decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each production-package&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains an alternative-based variable component and alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^A(A_i)\n+\nF^{R,A}(A_i)\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost contains a state-based variable component and alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)c^S(S_j)\n+\nF^{C,A}(A_i)\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)r^A(A_i)\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)c^S(S_j)\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^A(A_i)\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)c^S(S_j)\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$6(13)+14+18=110$<\/td><td>$6(5)+24+8=62$<\/td><td>$110-62=48$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$4(13)+14+9=75$<\/td><td>$4(7)+24+13=65$<\/td><td>$75-65=10$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$8(16)+22+18=168$<\/td><td>$8(5)+37+8=85$<\/td><td>$168-85=83$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$5(16)+22+9=111$<\/td><td>$5(7)+37+13=85$<\/td><td>$111-85=26$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong attendance and sponsorship<\/p><\/th><th scope=\"col\"><p>Limited attendance and sponsorship<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Standard hybrid package<\/p><\/th><td><p>48<\/p><\/td><td><p>10<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Immersive hybrid package<\/p><\/th><td><p>83<\/p><\/td><td><p>26<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-18", "name": "Cold-Storage Export Contract (C1--C3)", "section": "Three-Component Models", "layer1": "3 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A food-export company must select a cold-storage configuration before export demand and energy-market conditions are known. Revenue consists of a state-based rate per storage batch, a fixed capacity payment determined by the selected configuration, and a fixed export payment determined by the state. Variable cost per batch combines a configuration-based operating rate and a state-based energy surcharge. The selected configuration also produces a fixed setup cost.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use the modular cold-storage facility <li>$A_2$: Use the large cold-storage facility <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong export demand <li>$S_2$: Limited export demand <\/ol><\/p>\n<p>The quantities, measured in storage batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=9,\n\t\t&\n\t\tq(A_1,S_2)&=5,\n\t\t\\\\\n\t\tq(A_2,S_1)&=12,\n\t\t&\n\t\tq(A_2,S_2)&=7.\n\t\\end{aligned}$$<\/p>\n<p>The state-based revenue rates, in thousand USD per storage batch, are $$r^S(S_1)=10,\n\t\\qquad\n\tr^S(S_2)=7.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=20,\n\t\\qquad\n\tF^{R,A}(A_2)=30.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=16,\n\t\\qquad\n\tF^{R,S}(S_2)=8.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per storage batch, are $$c^A(A_1)=4,\n\t\\qquad\n\tc^A(A_2)=3.$$<\/p>\n<p>The state-based cost rates are $$c^S(S_1)=2,\n\t\\qquad\n\tc^S(S_2)=4.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=28,\n\t\\qquad\n\tF^{C,A}(A_2)=42.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use the modular cold-storage facility; Use the large cold-storage facility<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong export demand; Limited export demand<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Export demand and energy-market conditions revealed after the facility decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each storage-facility&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains a state-based variable component and alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)r^S(S_j)\n+\nF^{R,A}(A_i)\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost contains alternative-based and state-based variable components and an alternative-based fixed component: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right]\n+\nF^{C,A}(A_i).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)r^S(S_j)\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)r^S(S_j)\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$9(10)+20+16=126$<\/td><td>$9(4+2)+28=82$<\/td><td>$126-82=44$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$5(7)+20+8=63$<\/td><td>$5(4+4)+28=68$<\/td><td>$63-68=-5$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$12(10)+30+16=166$<\/td><td>$12(3+2)+42=102$<\/td><td>$166-102=64$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$7(7)+30+8=87$<\/td><td>$7(3+4)+42=91$<\/td><td>$87-91=-4$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong export demand<\/p><\/th><th scope=\"col\"><p>Limited export demand<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Modular cold-storage facility<\/p><\/th><td><p>44<\/p><\/td><td>$-5$<\/td><\/tr><tr><th scope=\"row\"><p>Large cold-storage facility<\/p><\/th><td><p>64<\/p><\/td><td>$-4$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The negative payoffs under limited export demand represent losses because the revenue earned does not cover the variable and fixed costs.<\/p>"}]}, {"id": "problem-19", "name": "Smart Manufacturing Contract (C1--C3)", "section": "Complete Four-Component Models", "layer1": "4 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A manufacturing company must select a production system before product demand and input-market conditions are known. Revenue per production batch combines a rate determined by the selected system and a rate determined by the state. Revenue also includes a fixed contract payment determined by the system and a fixed market incentive determined by the state.<\/p>\n<p>Variable cost per batch combines a system-based operating rate and a state-based material surcharge. Fixed cost consists of a setup cost determined by the selected system and a compliance cost determined by the state.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Use the conventional assembly system <li>$A_2$: Use the automated assembly system <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: Strong demand with favourable input conditions <li>$S_2$: Limited demand with expensive inputs <\/ol><\/p>\n<p>The quantities, measured in production batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=8,\n\t\t&\n\t\tq(A_1,S_2)&=5,\n\t\t\\\\\n\t\tq(A_2,S_1)&=11,\n\t\t&\n\t\tq(A_2,S_2)&=6.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per production batch, are $$r^A(A_1)=12,\n\t\\qquad\n\tr^A(A_2)=15.$$<\/p>\n<p>The state-based revenue rates, in thousand USD per production batch, are $$r^S(S_1)=4,\n\t\\qquad\n\tr^S(S_2)=2.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=18,\n\t\\qquad\n\tF^{R,A}(A_2)=28.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=14,\n\t\\qquad\n\tF^{R,S}(S_2)=7.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per production batch, are $$c^A(A_1)=5,\n\t\\qquad\n\tc^A(A_2)=6.$$<\/p>\n<p>The state-based cost rates, in thousand USD per production batch, are $$c^S(S_1)=2,\n\t\\qquad\n\tc^S(S_2)=4.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=24,\n\t\\qquad\n\tF^{C,A}(A_2)=38.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=9,\n\t\\qquad\n\tF^{C,S}(S_2)=15.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use the conventional assembly system; Use the automated assembly system<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>Strong demand with favourable input conditions; Limited demand with expensive inputs<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Demand and input-market conditions revealed after the production-system decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each production-system&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n+\nF^{R,A}(A_i)\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost also contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right]\n+\nF^{C,A}(A_i)\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$8(12+4)+18+14=160$<\/td><td>$8(5+2)+24+9=89$<\/td><td>$160-89=71$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$5(12+2)+18+7=95$<\/td><td>$5(5+4)+24+15=84$<\/td><td>$95-84=11$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$11(15+4)+28+14=251$<\/td><td>$11(6+2)+38+9=135$<\/td><td>$251-135=116$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$6(15+2)+28+7=137$<\/td><td>$6(6+4)+38+15=113$<\/td><td>$137-113=24$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>Strong demand, favourable inputs<\/p><\/th><th scope=\"col\"><p>Limited demand, expensive inputs<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Conventional assembly system<\/p><\/th><td><p>71<\/p><\/td><td><p>11<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Automated assembly system<\/p><\/th><td><p>116<\/p><\/td><td><p>24<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-20", "name": "Distribution Centre Automation (C1--C3)", "section": "Complete Four-Component Models", "layer1": "4 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>A retail company must select a distribution-centre configuration before order volume and energy-market conditions are known. Revenue per order batch combines a rate determined by the selected configuration and a rate determined by the state. Revenue also includes a fixed service payment determined by the configuration and a fixed delivery incentive determined by the state.<\/p>\n<p>Variable cost per order batch combines a configuration-based operating rate and a state-based energy surcharge. Fixed cost consists of an installation cost determined by the configuration and a compliance cost determined by the state.<\/p>\n<p>The company is comparing three alternatives: <ol> <li>$A_1$: Use the manual distribution configuration <li>$A_2$: Use the semi-automated distribution configuration <li>$A_3$: Use the robotic distribution configuration <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High order volume with favourable energy prices <li>$S_2$: Moderate order volume with expensive energy <\/ol><\/p>\n<p>The quantities, measured in hundreds of order batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=8,\n\t\t&\n\t\tq(A_1,S_2)&=5,\n\t\t\\\\\n\t\tq(A_2,S_1)&=11,\n\t\t&\n\t\tq(A_2,S_2)&=7,\n\t\t\\\\\n\t\tq(A_3,S_1)&=14,\n\t\t&\n\t\tq(A_3,S_2)&=8.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per hundred order batches, are $$\\begin{aligned}\n\t\tr^A(A_1)&=12,\n\t\t&\n\t\tr^A(A_2)&=15,\n\t\t&\n\t\tr^A(A_3)&=18.\n\t\\end{aligned}$$<\/p>\n<p>The state-based revenue rates are $$r^S(S_1)=4,\n\t\\qquad\n\tr^S(S_2)=2.$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$\\begin{aligned}\n\t\tF^{R,A}(A_1)&=16,\n\t\t&\n\t\tF^{R,A}(A_2)&=24,\n\t\t&\n\t\tF^{R,A}(A_3)&=35.\n\t\\end{aligned}$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$F^{R,S}(S_1)=15,\n\t\\qquad\n\tF^{R,S}(S_2)=8.$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per hundred order batches, are $$\\begin{aligned}\n\t\tc^A(A_1)&=5,\n\t\t&\n\t\tc^A(A_2)&=6,\n\t\t&\n\t\tc^A(A_3)&=8.\n\t\\end{aligned}$$<\/p>\n<p>The state-based cost rates are $$c^S(S_1)=2,\n\t\\qquad\n\tc^S(S_2)=4.$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$\\begin{aligned}\n\t\tF^{C,A}(A_1)&=22,\n\t\t&\n\t\tF^{C,A}(A_2)&=34,\n\t\t&\n\t\tF^{C,A}(A_3)&=50.\n\t\\end{aligned}$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$F^{C,S}(S_1)=9,\n\t\\qquad\n\tF^{C,S}(S_2)=16.$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Use the manual distribution configuration; Use the semi-automated distribution configuration; Use the robotic distribution configuration<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High order volume with favourable energy prices; Moderate order volume with expensive energy<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Order volume and energy-market conditions revealed after the distribution-configuration decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each distribution-configuration&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n+\nF^{R,A}(A_i)\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost also contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right]\n+\nF^{C,A}(A_i)\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$8(12+4)+16+15=159$<\/td><td>$8(5+2)+22+9=87$<\/td><td>$159-87=72$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$5(12+2)+16+8=94$<\/td><td>$5(5+4)+22+16=83$<\/td><td>$94-83=11$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$11(15+4)+24+15=248$<\/td><td>$11(6+2)+34+9=131$<\/td><td>$248-131=117$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$7(15+2)+24+8=151$<\/td><td>$7(6+4)+34+16=120$<\/td><td>$151-120=31$<\/td><\/tr><tr><th scope=\"row\">$(A_3,S_1)$<\/th><td>$14(18+4)+35+15=358$<\/td><td>$14(8+2)+50+9=199$<\/td><td>$358-199=159$<\/td><\/tr><tr><th scope=\"row\">$(A_3,S_2)$<\/th><td>$8(18+2)+35+8=203$<\/td><td>$8(8+4)+50+16=162$<\/td><td>$203-162=41$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High order volume<\/p><\/th><th scope=\"col\"><p>Moderate order volume<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Manual distribution configuration<\/p><\/th><td><p>72<\/p><\/td><td><p>11<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Semi-automated distribution configuration<\/p><\/th><td><p>117<\/p><\/td><td><p>31<\/p><\/td><\/tr><tr><th scope=\"row\"><p>Robotic distribution configuration<\/p><\/th><td><p>159<\/p><\/td><td><p>41<\/p><\/td><\/tr><\/tbody><\/table><\/div>"}]}, {"id": "problem-21", "name": "Electric Vehicle Charging Network (C1--C3)", "section": "Complete Four-Component Models", "layer1": "4 components", "layer2": ["AV", "SV", "AF", "SF"], "descriptionHtml": "<p>An energy company must select an electric vehicle charging-network design before charging demand and electricity-market conditions are known. Revenue per charging-session batch combines a rate determined by the selected network and a rate determined by the state. Revenue also includes a fixed service payment determined by the network and a fixed utilisation incentive determined by the state.<\/p>\n<p>Variable cost per charging-session batch combines a network-based equipment rate and a state-based electricity rate. Fixed cost consists of an infrastructure cost determined by the network and a maintenance cost determined by the state.<\/p>\n<p>The company is comparing two alternatives: <ol> <li>$A_1$: Build the neighbourhood charging network <li>$A_2$: Build the rapid-charging network <\/ol><\/p>\n<p>The possible states of nature are: <ol> <li>$S_1$: High utilisation with favourable electricity prices <li>$S_2$: Moderate utilisation with standard electricity prices <li>$S_3$: Low utilisation with expensive electricity <\/ol><\/p>\n<p>The quantities, measured in hundreds of charging-session batches, are $$\\begin{aligned}\n\t\tq(A_1,S_1)&=10,\n\t\t&\n\t\tq(A_1,S_2)&=7,\n\t\t&\n\t\tq(A_1,S_3)&=4,\n\t\t\\\\\n\t\tq(A_2,S_1)&=14,\n\t\t&\n\t\tq(A_2,S_2)&=9,\n\t\t&\n\t\tq(A_2,S_3)&=5.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based revenue rates, in thousand USD per hundred charging-session batches, are $$r^A(A_1)=11,\n\t\\qquad\n\tr^A(A_2)=16.$$<\/p>\n<p>The state-based revenue rates are $$\\begin{aligned}\n\t\tr^S(S_1)&=4,\n\t\t&\n\t\tr^S(S_2)&=3,\n\t\t&\n\t\tr^S(S_3)&=2.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based fixed revenues, in thousand USD, are $$F^{R,A}(A_1)=18,\n\t\\qquad\n\tF^{R,A}(A_2)=30.$$<\/p>\n<p>The state-based fixed revenues, in thousand USD, are $$\\begin{aligned}\n\t\tF^{R,S}(S_1)&=16,\n\t\t&\n\t\tF^{R,S}(S_2)&=10,\n\t\t&\n\t\tF^{R,S}(S_3)&=5.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based cost rates, in thousand USD per hundred charging-session batches, are $$c^A(A_1)=4,\n\t\\qquad\n\tc^A(A_2)=7.$$<\/p>\n<p>The state-based cost rates are $$\\begin{aligned}\n\t\tc^S(S_1)&=2,\n\t\t&\n\t\tc^S(S_2)&=3,\n\t\t&\n\t\tc^S(S_3)&=5.\n\t\\end{aligned}$$<\/p>\n<p>The alternative-based fixed costs, in thousand USD, are $$F^{C,A}(A_1)=25,\n\t\\qquad\n\tF^{C,A}(A_2)=45.$$<\/p>\n<p>The state-based fixed costs, in thousand USD, are $$\\begin{aligned}\n\t\tF^{C,S}(S_1)&=8,\n\t\t&\n\t\tF^{C,S}(S_2)&=12,\n\t\t&\n\t\tF^{C,S}(S_3)&=18.\n\t\\end{aligned}$$<\/p>\n<strong>Questions/Tasks.<\/strong>\n<ol>\n\t<li><strong>(C1, 1 points)<\/strong> <p>Interpreting decision alternatives, events, consequences, and states.<\/p><\/li>\n\t<li><strong>(C3, 3 points)<\/strong> <p>Calculating profit and building the payoff table.<\/p><\/li>\n<\/ol>", "solutionSections": [{"title": "C1: Interpreting decision alternatives, events, consequences, and states.", "contentHtml": "<div class=\"table-card\"><table class=\"data-table\"><caption>Decision elements<\/caption><tbody><tr><th scope=\"row\">Alternatives<\/th><td><p>Build the neighbourhood charging network; Build the rapid-charging network<\/p><\/td><\/tr><tr><th scope=\"row\">States of nature<\/th><td><p>High utilisation with favourable electricity prices; Moderate utilisation with standard electricity prices; Low utilisation with expensive electricity<\/p><\/td><\/tr><tr><th scope=\"row\">Uncertain event<\/th><td><p>Charging demand and electricity-market conditions revealed after the network-design decision<\/p><\/td><\/tr><tr><th scope=\"row\">Consequences/payoffs<\/th><td><p>Profit in thousand USD for each charging-network&ndash;state pair<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Revenue contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$R(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nr^A(A_i)+r^S(S_j)\n\\right]\n+\nF^{R,A}(A_i)\n+\nF^{R,S}(S_j).$$<\/p>\n<p>Cost also contains alternative-based and state-based variable components and alternative-based and state-based fixed components: $$C(A_i,S_j)\n=\nq(A_i,S_j)\n\\left[\nc^A(A_i)+c^S(S_j)\n\\right]\n+\nF^{C,A}(A_i)\n+\nF^{C,S}(S_j).$$<\/p>\n<p>Therefore, $$\\begin{aligned}\n\tP(A_i,S_j)\n\t={}&\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j)\n\t\\right\\}\n\t\\\\\n\t&-\n\t\\left\\{\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j)\n\t\\right\\}.\n\\end{aligned}$$<\/p>"}, {"title": "C3: Calculating profit and building the payoff table.", "contentHtml": "<p>For every alternative&ndash;state pair, calculate $$\\begin{aligned}\n\tR(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tr^A(A_i)+r^S(S_j)\n\t\\right]\n\t+\n\tF^{R,A}(A_i)\n\t+\n\tF^{R,S}(S_j),\n\t\\\\\n\tC(A_i,S_j)\n\t&=\n\tq(A_i,S_j)\n\t\\left[\n\tc^A(A_i)+c^S(S_j)\n\t\\right]\n\t+\n\tF^{C,A}(A_i)\n\t+\n\tF^{C,S}(S_j),\n\t\\\\\n\tP(A_i,S_j)\n\t&=\n\tR(A_i,S_j)-C(A_i,S_j).\n\\end{aligned}$$<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Cell<\/p><\/th><th scope=\"col\">$R(A_i,S_j)$<\/th><th scope=\"col\">$C(A_i,S_j)$<\/th><th scope=\"col\">$P(A_i,S_j)=R(A_i,S_j)-C(A_i,S_j)$<\/th><\/tr><\/thead><tbody><tr><th scope=\"row\">$(A_1,S_1)$<\/th><td>$10(11+4)+18+16=184$<\/td><td>$10(4+2)+25+8=93$<\/td><td>$184-93=91$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_2)$<\/th><td>$7(11+3)+18+10=126$<\/td><td>$7(4+3)+25+12=86$<\/td><td>$126-86=40$<\/td><\/tr><tr><th scope=\"row\">$(A_1,S_3)$<\/th><td>$4(11+2)+18+5=75$<\/td><td>$4(4+5)+25+18=79$<\/td><td>$75-79=-4$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_1)$<\/th><td>$14(16+4)+30+16=326$<\/td><td>$14(7+2)+45+8=179$<\/td><td>$326-179=147$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_2)$<\/th><td>$9(16+3)+30+10=211$<\/td><td>$9(7+3)+45+12=147$<\/td><td>$211-147=64$<\/td><\/tr><tr><th scope=\"row\">$(A_2,S_3)$<\/th><td>$5(16+2)+30+5=125$<\/td><td>$5(7+5)+45+18=123$<\/td><td>$125-123=2$<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The resulting payoff table is:<\/p>\n\t<div class=\"table-card\"><table class=\"data-table\"><thead><tr><th scope=\"col\"><p>Alternative<\/p><\/th><th scope=\"col\"><p>High utilisation<\/p><\/th><th scope=\"col\"><p>Moderate utilisation<\/p><\/th><th scope=\"col\"><p>Low utilisation<\/p><\/th><\/tr><\/thead><tbody><tr><th scope=\"row\"><p>Neighbourhood charging network<\/p><\/th><td><p>91<\/p><\/td><td><p>40<\/p><\/td><td>$-4$<\/td><\/tr><tr><th scope=\"row\"><p>Rapid-charging network<\/p><\/th><td><p>147<\/p><\/td><td><p>64<\/p><\/td><td><p>2<\/p><\/td><\/tr><\/tbody><\/table><\/div>\n<p>The negative payoff for the neighbourhood charging network under low utilisation represents a loss because the revenue earned does not cover the variable and fixed costs.<\/p>"}]}]
  };
  window.practiceData = practiceData;
  const escapeHtml = value => String(value).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"})[c]);
  function init() {
    const controls=document.getElementById("practice-selector-controls"), status=document.getElementById("practice-selector-status"), list=document.getElementById("practice-problems");
    if (!controls || !status || !list) return;
    const selected={section:new Set(),layer1:new Set(),layer2:new Set()};
    const summaries=new Map();
    function closeAll(except) { document.querySelectorAll(".practice-multiselect[open]").forEach(d=>{if(d!==except)d.open=false;}); }
    practiceData.filters.forEach(filter=>{
      const details=document.createElement("details"); details.className="practice-multiselect";
      const summary=document.createElement("summary"); summary.setAttribute("role","button"); summary.setAttribute("aria-label",filter.label); summaries.set(filter.key,summary);
      const label=document.createElement("span"); label.className="practice-multiselect__label"; label.textContent=filter.label;
      const value=document.createElement("span"); value.className="practice-multiselect__value"; value.textContent="Any"; summary.append(label,value);
      const menu=document.createElement("div"); menu.className="practice-multiselect__menu";
      filter.options.forEach(option=>{ const row=document.createElement("label"); row.className="practice-multiselect__option"; const input=document.createElement("input"); input.type="checkbox"; input.value=option; input.dataset.filter=filter.key; const text=document.createElement("span"); text.textContent=filter.descriptions?.[option] ? `${option} — ${filter.descriptions[option]}` : option; row.append(input,text); menu.append(row); });
      details.addEventListener("toggle",()=>{summary.setAttribute("aria-expanded",String(details.open));if(details.open)closeAll(details);}); summary.setAttribute("aria-expanded","false"); details.append(summary,menu); controls.append(details);
    });
    const clear=document.createElement("button"); clear.type="button"; clear.className="practice-selector__clear"; clear.textContent="Clear all filters"; controls.append(clear);
    function matches(problem) { return practiceData.filters.every(f=>!selected[f.key].size || (Array.isArray(problem[f.key]) ? [...selected[f.key]].some(v=>problem[f.key].includes(v)) : selected[f.key].has(problem[f.key]))); }
    function render() {
      practiceData.filters.forEach(f=>{const vals=[...selected[f.key]]; summaries.get(f.key).querySelector(".practice-multiselect__value").textContent=vals.length?vals.join(", "):"Any";});
      const found=practiceData.problems.filter(matches); list.innerHTML=found.map(p=>`<section id="${p.id}" class="content-card practice-problem" data-region="problem-card"><h2>${escapeHtml(p.name)}</h2><ul class="practice-problem__metadata"><li><strong>Section:</strong> ${escapeHtml(p.section)}</li><li><strong>Layer 1:</strong> ${escapeHtml(p.layer1)}</li><li><strong>Layer 2:</strong> ${p.layer2.length?p.layer2.map(escapeHtml).join(", "):"None (direct totals)"}</li></ul><div class="example"><h3>Problem description</h3><div class="content-block">${p.descriptionHtml}</div>${p.solutionSections.map((s,i)=>`<div class="subsection-minimize collapsed" data-region="subsection"><button class="subsection-toggle" type="button" aria-expanded="false" aria-controls="${p.id}-solution-${i}"><span class="toggle-label">${escapeHtml(s.title)}</span><span class="toggle-icon" aria-hidden="true">+</span></button><div class="subsection-content" id="${p.id}-solution-${i}" role="region"><div class="content-block">${s.contentHtml}</div></div></div>`).join("")}</div></section>`).join("");
      status.textContent=`Showing ${found.length} of ${practiceData.problems.length} problems.`;
      if(window.MathJax?.typesetPromise) window.MathJax.typesetPromise([list]).catch(e=>console.error("MathJax typesetting failed:",e));
    }
    controls.addEventListener("change",e=>{if(!e.target.matches('input[type="checkbox"]'))return; const set=selected[e.target.dataset.filter]; e.target.checked?set.add(e.target.value):set.delete(e.target.value); render();});
    clear.addEventListener("click",()=>{Object.values(selected).forEach(s=>s.clear());controls.querySelectorAll('input[type="checkbox"]').forEach(i=>i.checked=false);render();});
    list.addEventListener("click",e=>{const b=e.target.closest(".subsection-toggle");if(!b)return;const box=b.closest(".subsection-minimize"),open=b.getAttribute("aria-expanded")!=="true";b.setAttribute("aria-expanded",String(open));b.querySelector(".toggle-icon").textContent=open?"−":"+";box.classList.toggle("collapsed",!open);});
    document.addEventListener("click",e=>{if(!e.target.closest(".practice-multiselect"))closeAll();}); render();
  }
  document.readyState==="loading"?document.addEventListener("DOMContentLoaded",init):init();
})();
